def main():
    path = "phase2/output/deliverable04/labeling_sample.csv"
    df = pd.read_csv(path, dtype=str, keep_default_na=False)
    labels = pd.DataFrame(LABELS)
    merged = df.merge(labels, on="candidate_id", how="left", suffixes=("", "_al2"))
    has_label = merged["label_al2"].notna()
    blank = merged["label"].astype(str).str.strip().eq("")
    apply_mask = has_label & blank
    merged.loc[apply_mask, "label"] = merged.loc[apply_mask, "label_al2"]
    merged.loc[apply_mask, "notes"] = merged.loc[apply_mask, "notes_al2"]
    merged[df.columns].to_csv(path, index=False)
    print(f"Applied {int(apply_mask.sum())} labels to labeling_sample.csv")


if __name__ == "__main__":
    main()
